// Evaluate thresholds: one row per metric from ops.w22_metrics -> zero or more signals.
// THRESHOLDS mirrors automation/W22.md section 1. Change both together (W22.test.mjs checks the keys match).
const THRESHOLDS = {
  raw_cpl_zar: { key: 'cpl_kill_raw', sev: 'red', limit: 250, cmp: 'gt', gate: (m) => (m.context.spend_zar || 0) >= 3000,
    what: (m) => `Raw CPL R${Math.round(m.value)} above R250 kill line (${m.scope})`,
    impact: 'Spend is buying leads above the 3.4 model', action: 'Pause bottom 50% of creatives; tighten questions (3.4)' },
  qualify_rate: { key: 'qualify_rate_low', sev: 'red', limit: 0.60, cmp: 'lt', gate: (m) => (m.context.spend_zar || 0) >= 3000,
    what: (m) => `Qualify rate ${Math.round(m.value * 100)}% below 60% (${m.scope})`,
    impact: 'Raw leads are not qualifying', action: 'Pause bottom 50% of creatives; tighten questions (3.4)' },
  cost_per_qualified_zar: { key: 'cpql_kill', sev: 'red', limit: 400, cmp: 'gt', gate: (m) => (m.context.days_live || 0) >= 14,
    what: (m) => `Cost per qualified lead R${Math.round(m.value)} above R400 after 14 days (${m.scope})`,
    impact: 'Cycle economics at risk (Section 3)', action: 'Stop and decide with Jonathan (3.4)' },
  show_rate_14d: { key: 'show_rate_low', sev: 'red', limit: 0.50, cmp: 'lt', gate: (m) => (m.n || 0) >= 8,
    what: (m) => `Show rate ${Math.round(m.value * 100)}% over 14 days (${m.scope}, n=${m.n})`,
    impact: 'Booked meetings are not being attended', action: 'Review reminder sequence and qualification (3.4)' },
  first_message_sla_breaches: { key: 'first_msg_sla', sev: 'red', limit: 0, cmp: 'gt', gate: () => true,
    what: (m) => `${m.value} lead(s) waited over 60 s for the first WhatsApp (worst ${m.context.worst_seconds || '?'} s)`,
    impact: 'Warmest moment lost; W06 or the send path is slow or down', action: 'Check W06 executions and WhatsApp send errors' },
  leads_last_hour: { key: 'intake_spike', sev: 'red', limit: null, cmp: 'spike', gate: (m) => m.value >= 20,
    what: (m) => `${m.value} leads in the last hour vs normal ${m.context.baseline_hourly_median_7d || 0}`,
    impact: 'Possible bot or SMS-pumping attack on /lead (6B.5)', action: 'Check Turnstile and rate-limit logs; pause the form if fake' },
  oauth_refresh_failures_24h: { key: 'calendar_token_failed', sev: 'red', limit: 0, cmp: 'gt', gate: () => true,
    what: (m) => `Calendar token refresh failing for ${m.scope}`,
    impact: 'Slots and bookings fail for this broker; list fallback in use', action: 'Ask the broker to reconnect Outlook in the portal' },
  secret_days_to_expiry: { key: 'token_expiring', sev: 'tiered', limit: 30, cmp: 'lte', gate: () => true,
    what: (m) => `${m.scope.replace('secret:', '')} expires in ${Math.max(0, Math.floor(m.value))} days`,
    impact: 'Integration stops at expiry', action: 'Rotate per SECURITY.md section 1 and update ops.secret_inventory' },
  backup_hours_since_success: { key: 'backup_stale', sev: 'red', limit: 26, cmp: 'gt', gate: () => true,
    what: (m) => `Last good pg_dump ${Math.floor(m.value)} h ago`,
    impact: 'Consent records (legal evidence) not backed up off-server', action: 'Check pg_dump_nightly.sh log on the VPS' },
  restore_test_days_since: { key: 'restore_test_overdue', sev: 'amber', limit: 35, cmp: 'gt', gate: () => true,
    what: (m) => `Restore test last passed ${Math.floor(m.value)} days ago`,
    impact: 'Monthly tested-restore target missed', action: 'Run automation/backup/restore.sh --test' },
};

function breached(t, m) {
  if (t.cmp === 'gt') return m.value > t.limit;
  if (t.cmp === 'lt') return m.value < t.limit;
  if (t.cmp === 'lte') return m.value <= t.limit;
  if (t.cmp === 'spike') return m.value > 3 * Math.max(1, Number(m.context.baseline_hourly_median_7d || 0));
  return false;
}

const out = [];
for (const item of $input.all()) {
  const r = item.json || {};
  if (r.value === null || r.value === undefined || r.value === '') continue;
  const m = { metric: r.metric, scope: r.scope || 'global', value: Number(r.value), n: Number(r.n || 0),
    context: typeof r.context === 'string' ? JSON.parse(r.context || '{}') : (r.context || {}) };
  const t = THRESHOLDS[m.metric];
  if (!t || !Number.isFinite(m.value) || !t.gate(m) || !breached(t, m)) continue;
  const severity = t.sev === 'tiered' ? (m.value <= 7 ? 'red' : 'amber') : t.sev;
  out.push({ json: {
    signal_key: t.key, scope: m.scope, severity, source: 'W22.sweep', metric: m.metric,
    value: m.value, limit: t.limit, what: t.what(m), impact: t.impact, first_action: t.action,
    since: r.since || new Date().toISOString(),
  } });
}
return out;

// Build an encrypted health-check ping in the exact request format Meta sends to a Flow endpoint
// (RSA-OAEP-SHA256 wrapped AES-128-GCM key, 16-byte IV, ciphertext||tag, all base64), signed with
// X-Hub-Signature-256. It is a test client mirroring Meta's reference endpoint, not a new scheme.
const crypto = require('crypto');
const url = $env.FLOW_ENDPOINT_URL;
const pub = String($env.FLOW_PUBLIC_KEY || '').replace(/\\n/g, '\n');
if (!url || !pub.includes('PUBLIC KEY')) return [{ json: { skip: true, reason: 'flow_not_configured' } }];
const aesKey = crypto.randomBytes(16);
const iv = crypto.randomBytes(16);
const cipher = crypto.createCipheriv('aes-128-gcm', aesKey, iv);
const data = Buffer.concat([cipher.update(JSON.stringify({ version: '3.0', action: 'ping' }), 'utf8'), cipher.final(), cipher.getAuthTag()]);
const wrapped = crypto.publicEncrypt({ key: pub, padding: crypto.constants.RSA_PKCS1_OAEP_PADDING, oaepHash: 'sha256' }, aesKey);
const body = JSON.stringify({ encrypted_flow_data: data.toString('base64'), encrypted_aes_key: wrapped.toString('base64'), initial_vector: iv.toString('base64') });
const sig = 'sha256=' + crypto.createHmac('sha256', $env.META_APP_SECRET || '').update(body).digest('hex');
return [{ json: { skip: false, url, body, signature: sig, k: aesKey.toString('base64'), iv: iv.toString('base64') } }];

// Judge the ping: decrypt the response with the same AES key and the bit-flipped IV
// (as Meta's reference endpoint encrypts it) and expect {"data":{"status":"active"}} within 3 s.
const crypto = require('crypto');
const req = $('Build Flow ping').first().json;
if (req.skip) return [{ json: { failing: false, skip: true } }];
const res = $input.first().json || {};
let ok = false, reason = 'no_response';
try {
  if (res.statusCode !== 200) { reason = `http_${res.statusCode || 'timeout'}`; }
  else {
    const buf = Buffer.from(String(res.body || res.data || '').trim(), 'base64');
    const key = Buffer.from(req.k, 'base64');
    const flipped = Buffer.from(Buffer.from(req.iv, 'base64').map((b) => ~b & 0xff));
    const d = crypto.createDecipheriv('aes-128-gcm', key, flipped);
    d.setAuthTag(buf.subarray(buf.length - 16));
    const plain = Buffer.concat([d.update(buf.subarray(0, buf.length - 16)), d.final()]).toString('utf8');
    const j = JSON.parse(plain);
    ok = j && j.data && j.data.status === 'active';
    reason = ok ? 'ok' : 'bad_status';
  }
} catch (e) { reason = 'decrypt_failed'; }
return [{ json: { failing: !ok, reason } }];

// Turn the ping verdict (+ whether booking_ui was reverted) into a signal for the policy.
const v = $('Judge Flow ping').first().json;
if (v.skip || !v.failing) return [];
const reverted = Number(($input.first().json || {}).reverted || 0);
return [{ json: { kind: 'signal', signal_key: 'flow_ping_fail', scope: 'flow:booking', severity: 'red', source: 'W22.hourly',
  what: `Booking Flow endpoint ping failed (${v.reason})`,
  impact: reverted ? `booking_ui reverted to list for ${reverted} brand(s); leads get the 10-slot list` : 'Flow bookings may fail; list fallback applies',
  first_action: 'Check the Flow endpoint container and FLOW_PRIVATE_KEY; re-run Meta health check', since: new Date().toISOString() } }];

// Hourly reachability of the public surfaces. VPS-down detection itself lives in the external monitor
// (automation/vps/UPTIME.md) because a dead VPS cannot alert about itself.
const t = [];
const add = (name, url) => { if (url && /^https:\/\//.test(url)) t.push({ json: { target: name, url } }); };
add('api', $env.N8N_PUBLIC_URL ? `${$env.N8N_PUBLIC_URL.replace(/\/$/, '')}/healthz` : null);
add('app', $env.CONSOLE_URL);
add('portal', $env.PORTAL_URL);
add('consumer', $env.CONSUMER_DOMAIN ? `https://${$env.CONSUMER_DOMAIN}/` : null);
return t;

// 2xx/3xx = up. Down -> red; 'api' down while W22 still runs means Traefik/DNS/tunnel, not the VPS.
const targets = $('Uptime targets').all().map((i) => i.json);
const out = [];
$input.all().forEach((i, idx) => {
  const r = i.json || {};
  const t = targets[idx] || { target: 'unknown' };
  const code = Number(r.statusCode || 0);
  if (code >= 200 && code < 400) return;
  out.push({ json: { kind: 'signal', signal_key: 'uptime_down', scope: `target:${t.target}`, severity: 'red',
    always_send: t.target === 'api', source: 'W22.hourly',
    what: `${t.target} unreachable (HTTP ${code || 'timeout'})`,
    impact: t.target === 'api' ? 'Webhooks may not reach n8n (tunnel, Traefik or DNS)' : 'A public page or the console is down',
    first_action: 'See automation/vps/UPTIME.md runbook', since: new Date().toISOString() } });
});
return out;

// WhatsApp number health (hourly). A drop vs the last stored rating is a signal; RED or a lower
// messaging tier is always-send (WABA restriction class). State kept in workflow static data.
const st = $getWorkflowStaticData('global');
const r = $input.first().json || {};
const RANK = { GREEN: 3, YELLOW: 2, RED: 1, UNKNOWN: 0 };
const out = [];
if (r.error || !r.quality_rating) {
  if (r.error && r.error.code === 190) {
    out.push({ json: { kind: 'signal', signal_key: 'token_invalid', scope: 'meta:system_user', severity: 'red', source: 'W22.hourly',
      what: 'Meta system-user token rejected (OAuth 190)', impact: 'WhatsApp, Ads and CAPI calls fail',
      first_action: 'Regenerate the system-user token per SECURITY.md section 1', since: new Date().toISOString() } });
  }
  return out;
}
const now = String(r.quality_rating).toUpperCase();
const prev = st.waba_quality || 'GREEN';
const tierNow = String(r.messaging_limit_tier || '');
const tierPrev = st.waba_tier || tierNow;
// TIER_250 / TIER_1K / TIER_10K / TIER_100K / TIER_UNLIMITED -> daily conversation limit as a number
const tierNum = (t) => { if (/UNLIMITED/.test(t)) return 1e9; const m = String(t).match(/(\d+)(K?)/); return m ? Number(m[1]) * (m[2] ? 1000 : 1) : 0; };
if ((RANK[now] ?? 0) < (RANK[prev] ?? 3) || tierNum(tierNow) < tierNum(tierPrev)) {
  out.push({ json: { kind: 'signal', signal_key: now === 'RED' || tierNum(tierNow) < tierNum(tierPrev) ? 'waba_restriction' : 'waba_quality',
    scope: 'phone:primary', severity: 'red', source: 'W22.hourly',
    what: `WhatsApp quality ${prev} -> ${now}${tierNow !== tierPrev ? `, tier ${tierPrev} -> ${tierNow}` : ''}`,
    impact: 'Sending limits may drop; risk of restriction', first_action: 'Check WhatsApp Manager; prepare standby number',
    since: new Date().toISOString() } });
}
st.waba_quality = now; st.waba_tier = tierNow;
return out;

// Daily deliverability check (6B.6, monitored in W22): DKIM selector CNAMEs and DMARC TXT on leadvelocity.co.za.
const d = 'leadvelocity.co.za';
return [
  { json: { check: 'dmarc', url: `https://dns.google/resolve?name=_dmarc.${d}&type=TXT` } },
  { json: { check: 'dkim1', url: `https://dns.google/resolve?name=selector1._domainkey.${d}&type=CNAME` } },
  { json: { check: 'dkim2', url: `https://dns.google/resolve?name=selector2._domainkey.${d}&type=CNAME` } },
];

// Judge the daily DNS results. Missing DMARC/DKIM = amber (pulse), not a night-time page.
const checks = $('DNS checks').all().map((i) => i.json);
const out = [];
$input.all().forEach((i, idx) => {
  const c = checks[idx] || {};
  const ans = (i.json && i.json.Answer) || [];
  const ok = c.check === 'dmarc' ? ans.some((a) => /v=DMARC1/i.test(String(a.data))) : ans.length > 0;
  if (!ok) out.push({ json: { kind: 'signal', signal_key: 'email_auth_missing', scope: `dns:${c.check}`, severity: 'amber', source: 'W22.daily',
    what: `${c.check.toUpperCase()} record missing for leadvelocity.co.za`, impact: 'Invites and invoices from howzit@ may land in spam',
    first_action: 'Apply automation/dns/DNS.md section 4', since: new Date().toISOString() } });
});
return out;

// Normalise a signal handed in by another workflow (Execute Workflow), the uptime-monitor callback,
// or an n8n Error Trigger. Accepts our own shape or raw Meta/Paystack change objects.
// Unknown shapes are not dropped: they become an amber 'unknown_signal' so nothing is silently lost.
const CRITICAL_WORKFLOWS = /^(W01|W02|W03|W05|W06|W16|W22|W26|W28)\b/;
// Registered producer signals (W22.md section 1): defaults applied under the producer's own fields, so a
// partial payload still reads well. Unregistered own-shape keys still pass through (producer-defined rows).
const PRODUCER_SIGNALS = {
  // W27 Meta asset health (I-26): ad account / Page / pixel / CAPI / Lead form problems. WABA_* codes arrive as waba_restriction instead.
  meta_asset_health: { severity: 'red', always_send: false, scope: 'brand:unknown', source: 'W27',
    what: 'Meta asset health alert', impact: 'Ads, WhatsApp or lead capture may be affected',
    first_action: 'Open the console Ads screen, then Business Settings for the failing asset' },
  // W20 /ms/callback (I-41i): Microsoft rejected the broker-connect app (AADSTS7000215 / 7000222 / 700016, invalid_client).
  // App-wide: one scope for all brokers, so one alert per 24 h however many brokers try. Red -> both phones.
  ms_client_secret_invalid: { severity: 'red', always_send: false, scope: 'ms_app:broker_connect', source: 'W20',
    what: 'Microsoft rejected the broker-connect app credentials', impact: 'No broker can connect or reconnect Outlook until the client secret is fixed',
    first_action: 'Rotate the client secret in Entra ID and update the W20 n8n credential' },
  // W34 POPIA operations (I-38b). W34 sends {kind, workflow:'W34', to, severity: red|amber|info, message, deep_link, dsr_id?, to_broker_id?, first_name?}.
  // 'to' here is the registry recipient: io = W34_IO_RECIPIENT (the Information Officer, jonathan|kg), both = both partners,
  // broker = the broker row (no ops phone; W22 records it, the broker template send is I-38c). 'info' is stored as amber (pulse).
  // notify_now: an amber that still goes straight to its recipient by WhatsApp (start of the 30-day POPIA clock); never escalates.
  dsar_received: { severity: 'amber', notify_now: true, to: 'io', source: 'W34', scope: 'dsr:unknown',
    what: 'New data-subject request', impact: 'POPIA 30-day clock started', first_action: 'Verify identity in the console Compliance screen' },
  dsar_due: { severity: 'amber', to: 'io', source: 'W34', scope: 'dsr:clock',
    what: 'Data-subject request due within 7 days or unverified', impact: 'POPIA 30-day deadline approaching', first_action: 'Open the console Compliance screen' },
  dsar_overdue: { severity: 'red', to: 'both', source: 'W34', scope: 'dsr:clock',
    what: 'Data-subject request overdue', impact: 'POPIA 30-day deadline missed', first_action: 'Answer the request today from the console Compliance screen' },
  dsar_erased: { severity: 'amber', to: 'io', source: 'W34', scope: 'dsr:unknown',
    what: 'Data-subject erasure completed', impact: 'Lead data erased and number suppressed', first_action: 'None; evidence kept in retention_log' },
  broker_dsr_erase: { severity: 'amber', to: 'broker', source: 'W34', scope: 'broker:unknown',
    what: 'Broker must delete an erased client', impact: 'The broker holds a copy of the erased lead', first_action: 'Broker notice via template broker_dsr_erase (I-38c)' },
  w34_retention_failure: { severity: 'red', to: 'both', source: 'W34', scope: 'w34:nightly',
    what: 'W34 retention job failed', impact: 'Personal information may be kept past its retention period', first_action: 'Open the W34 execution and the nightly evidence file' },
  w34_monthly_report: { severity: 'amber', to: 'jonathan', source: 'W34', scope: 'w34:monthly',
    what: 'W34 monthly POPIA report ready', impact: 'Register P7/P8 evidence for the month', first_action: 'Read the monthly report in the evidence folder' },
};
const PARTNERS = ['jonathan', 'kg'];
const IO = PARTNERS.includes(String($env.W34_IO_RECIPIENT || '').toLowerCase()) ? String($env.W34_IO_RECIPIENT).toLowerCase() : 'jonathan';
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const nowIso = new Date().toISOString();
  // 1. Acknowledgement (console or a forwarded WhatsApp "ACK <id>")
  if (j.type === 'ack' && j.notification_id) {
    out.push({ json: { kind: 'ack', notification_id: String(j.notification_id), acked_by: String(j.acked_by || 'unknown') } });
    continue;
  }
  let s = null;
  let recognised = false; // a known event that is benign (e.g. template APPROVED) produces no signal
  // 2. n8n Error Trigger payload
  if (j.execution && j.workflow) {
    const wf = String(j.workflow.name || 'unknown');
    const crit = CRITICAL_WORKFLOWS.test(wf);
    s = { signal_key: 'workflow_failed', scope: `workflow:${wf}`, severity: crit ? 'red' : 'amber',
      what: `Workflow ${wf} failed at node ${j.execution.lastNodeExecuted || '?'}`,
      impact: crit ? 'A lead-path or money-path workflow is failing' : 'A support workflow is failing',
      first_action: 'Open the failed execution in n8n', source: 'n8n.error' };
  }
  // 3. Raw WhatsApp Business Account change (forwarded by the W03 ingress / W27)
  else if (j.field === 'message_template_status_update' && j.value) {
    recognised = true;
    const ev = String(j.value.event || '').toUpperCase();
    if (['REJECTED', 'PAUSED', 'DISABLED', 'FLAGGED'].includes(ev)) {
      s = { signal_key: 'template_rejected', scope: `template:${j.value.message_template_name || j.value.message_template_id}`,
        severity: 'red', what: `WhatsApp template ${j.value.message_template_name || ''} ${ev.toLowerCase()}`,
        impact: 'Messages using this template cannot be sent', first_action: 'Edit wording in console and resubmit',
        source: 'meta.webhook' };
    }
  } else if (j.field === 'phone_number_quality_update' && j.value) {
    recognised = true;
    const ev = String(j.value.event || '').toUpperCase();
    if (ev && ev !== 'UNFLAGGED' && ev !== 'UPGRADE' && ev !== 'ONBOARDING') {
      s = { signal_key: 'waba_quality', scope: `phone:${j.value.display_phone_number ? 'primary' : 'unknown'}`,
        severity: 'red', always_send: ev === 'FLAGGED' || ev === 'DOWNGRADE',
        what: `WhatsApp number quality ${ev.toLowerCase()} (limit ${j.value.current_limit || '?'})`,
        impact: 'Sending limits may drop; risk of restriction', first_action: 'Check quality in WhatsApp Manager; prepare standby number',
        source: 'meta.webhook' };
    }
  } else if (j.field === 'account_update' && j.value) {
    s = { signal_key: 'waba_restriction', scope: 'waba', severity: 'red', always_send: true,
      what: `WhatsApp account update: ${String(j.value.event || 'unknown').toLowerCase()}`,
      impact: 'WhatsApp sending may be restricted', first_action: 'Open WhatsApp Manager; switch to standby number if restricted',
      source: 'meta.webhook' };
  }
  // 4. Raw Paystack failure (forwarded by W16/W19 after signature check)
  else if (j.event && /^(invoice\.payment_failed|charge\.failed|subscription\.not_renew)$/.test(j.event)) {
    s = { signal_key: 'failed_debit', scope: `paystack:${(j.data && (j.data.subscription_code || j.data.reference)) || 'unknown'}`,
      severity: 'red', always_send: true, what: `Payment failed (${j.event})`,
      impact: 'Cycle renewal at risk; W19 retry day 1 and 3 then pay link', first_action: 'Check the invoice in the console',
      source: 'paystack' };
  }
  // 5. Uptime monitor callback: our contract {monitor, state: down|up, since}
  else if (j.body && j.body.monitor && j.body.state) {
    const b = j.body;
    const down = String(b.state).toLowerCase() === 'down';
    const isApi = /^api\b|api\./.test(String(b.monitor));
    s = { signal_key: down ? 'uptime_down' : 'uptime_recovered', scope: `monitor:${b.monitor}`,
      severity: down ? 'red' : 'amber', always_send: down && isApi,
      what: down ? `${b.monitor} is down` : `${b.monitor} recovered (down ${b.duration || '?'})`,
      impact: down ? (isApi ? 'Webhooks and the Flow endpoint are unreachable' : 'A public site is unreachable') : 'Downtime counted against the 99.5% SLO',
      first_action: down ? 'See automation/vps/UPTIME.md runbook' : 'None; logged for the uptime SLO', source: 'uptime.monitor', since: b.since };
  }
  // 6a. W34 shape: 'kind' names a registered W34 signal (I-38b). Severity info -> amber (pulse); recipients from the registry.
  else if (!j.signal_key && j.kind && PRODUCER_SIGNALS[j.kind] && PRODUCER_SIGNALS[j.kind].source === 'W34') {
    const def = PRODUCER_SIGNALS[j.kind];
    const sev = j.severity === 'red' ? 'red' : (j.severity === 'amber' || j.severity === 'info') ? 'amber' : def.severity;
    const scope = j.to_broker_id ? `broker:${j.to_broker_id}` : j.dsr_id ? `dsr:${j.dsr_id}` : def.scope;
    const recipients = def.to === 'io' ? [IO] : def.to === 'both' ? PARTNERS.slice() : def.to === 'broker' ? [scope] : [def.to];
    s = { signal_key: j.kind, scope, severity: sev, always_send: false, notify_now: Boolean(def.notify_now) && sev === 'amber',
      recipients, info: j.severity === 'info', source: 'W34', what: j.message || def.what, impact: def.impact,
      first_action: j.deep_link ? `Open ${j.deep_link}` : def.first_action, dsr_id: j.dsr_id || undefined, first_name: j.first_name || undefined };
  }
  // 6. Our own shape from W07 / W14 / W17 / W18 / W19 / W20 / W24 / W25 / W26 / W27 / W34
  else if (j.signal_key) {
    const def = PRODUCER_SIGNALS[j.signal_key];
    s = def ? { ...def, ...Object.fromEntries(Object.entries(j).filter(([, v]) => v !== undefined && v !== null && v !== '')) } : { ...j };
    if (def) s.severity = s.severity === 'amber' ? 'amber' : 'red';
  }
  if (!s && recognised) continue;
  if (!s) {
    s = { signal_key: 'unknown_signal', scope: 'w22', severity: 'amber', what: 'W22 received a signal it could not read',
      impact: 'A producer is sending the wrong shape', first_action: 'Check the producer against W22.md section 3', source: 'W22' };
  }
  out.push({ json: { kind: 'signal', scope: 'global', severity: 'red', since: nowIso, source: 'unknown', ...s } });
}
return out;

